files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
  --focus: #f5c542;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: radial-gradient(circle at 20% 30%, #0f3460 0%, transparent 40%),
                    radial-gradient(circle at 80% 70%, #0f3460 0%, transparent 40%);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 0;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 8px 8px 0 #0a0a1a;
}

h1 {
  margin: 0 0 24px;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #0a0a1a;
}

.question {
  font-size: 2rem;
  font-weight: 700;
  margin: 0 0 24px;
  min-height: 2.5rem;
  letter-spacing: 1px;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

button {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: 700;
  cursor: pointer;
  border: 3px solid var(--border);
  border-radius: 0;
  transition: transform 0.05s, background 0.15s, box-shadow 0.05s;
}

.answer-btn {
  flex: 1;
  padding: 16px 8px;
  background: var(--border);
  color: var(--text);
  box-shadow: 4px 4px 0 #0a0a1a;
}

.answer-btn:hover:not(:disabled) {
  background: #1a4a7a;
  border-color: var(--accent);
}

.answer-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.answer-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #0a0a1a;
}

.answer-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.score-line {
  font-size: 1.125rem;
  color: var(--muted);
  margin: 0 0 24px;
}

#score {
  font-weight: 700;
  color: var(--accent);
  font-size: 1.25rem;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.ctrl-btn {
  padding: 12px 24px;
  background: var(--accent);
  color: #fff;
  box-shadow: 4px 4px 0 #0a0a1a;
}

.ctrl-btn:hover {
  background: #ff5a75;
}

.ctrl-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.ctrl-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #0a0a1a;
}

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  .question { font-size: 1.5rem; }
  .answers { gap: 10px; }
  .answer-btn { padding: 14px 6px; font-size: 1.125rem; }
  .ctrl-btn { padding: 10px 18px; font-size: 1rem; }
}

(function () {
  'use strict';

  var state = {
    questionIndex: 0,
    score: 0,
    locked: false,
    finished: false
  };

  var questions = [
    { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
    { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
  ];

  var questionEl = document.getElementById('question');
  var answerA = document.getElementById('answer-a');
  var answerB = document.getElementById('answer-b');
  var scoreEl = document.getElementById('score');
  var nextBtn = document.getElementById('next');
  var restartBtn = document.getElementById('restart');

  function render() {
    if (state.finished) {
      questionEl.textContent = 'Finished';
      answerA.disabled = true;
      answerB.disabled = true;
      nextBtn.disabled = true;
      return;
    }
    var q = questions[state.questionIndex];
    questionEl.textContent = q.text;
    answerA.textContent = q.a;
    answerB.textContent = q.b;
    answerA.disabled = state.locked;
    answerB.disabled = state.locked;
    nextBtn.disabled = !state.locked;
    scoreEl.textContent = String(state.score);
  }

  function handleAnswer(choice) {
    if (state.locked || state.finished) return;
    state.locked = true;
    var q = questions[state.questionIndex];
    if (choice === q.correct) {
      state.score += 1;
    }
    render();
  }

  answerA.addEventListener('click', function () { handleAnswer('a'); });
  answerB.addEventListener('click', function () { handleAnswer('b'); });

  nextBtn.addEventListener('click', function () {
    if (!state.locked || state.finished) return;
    if (state.questionIndex < questions.length - 1) {
      state.questionIndex += 1;
      state.locked = false;
      render();
    } else {
      state.finished = true;
      render();
    }
  });

  restartBtn.addEventListener('click', function () {
    state.questionIndex = 0;
    state.score = 0;
    state.locked = false;
    state.finished = false;
    render();
  });

  render();
})();
